SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции2001.YEAR, Станции2001.NUST, Станции2001.E, Станции2001.EOTP, Станции2001.EURT, Станции2001.EUST, Станции2001.Q, Станции2001.TURT, Станции2001.TUST, Станции2001.B, Станции2001.GAZ, Станции2001.MAZUT, Станции2001.TORF, Станции2001.SLAN, Станции2001.GTT, Станции2001.PROCH, Станции2001.UGOL, Станции2001.DON, Станции2001.PODM, Станции2001.PECH, Доп_угли2001.int, Доп_угли2001.vork, Станции2001.ARKT, Станции2001.KUZN, Станции2001.URAL, Доп_угли2001.sver, Доп_угли2001.chel, Доп_угли2001.kizel, Станции2001.BASHK, Станции2001.EKIB, Станции2001.KARAG, Станции2001.KAN, Доп_угли2001.nazar, Доп_угли2001.ibor, Доп_угли2001.berez, Доп_угли2001.per, Станции2001.IRKUT, Доп_угли2001.azey, Доп_угли2001.cher, Станции2001.HAK, Станции2001.TUV, Станции2001.BUR, Доп_угли2001.gusin, Доп_угли2001.tugn, Станции2001.CHIT, Станции2001.NER AS Выражение1, Станции2001.RAICH AS Выражение2, Станции2001.URG, Станции2001.PRIM, Станции2001.LUCH, Станции2001.MAG, Станции2001.SAH, Станции2001.QOTR, Станции2001.SNK, Станции2001.EWTP, Станции2001.NT, Станции2001.OBOR, Станции2001.VED, Станции2001.OBL, Станции2001.DEP, Станции2001.OES, Станции2001.ER, Станции2001.NUMB1120, IIf([ved]<3,1,2) AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group]
FROM (((Станции2001 INNER JOIN Имена_станций ON Станции2001.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции2001.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции2001.OBL=Имена_областей.OBL) LEFT JOIN Доп_угли2001 ON (Станции2001.YEAR=Доп_угли2001.YEAR) AND (Станции2001.NUMB1120=Доп_угли2001.NUMB1120);
